<?php
require_once __DIR__.'/../models/Producto.php';
class ProductoController { private $m; function __construct(){$this->m=new Producto();} function listar(){$productos=$this->m->listar();require __DIR__.'/../views/productos.php';} function crear(){$producto=null;require __DIR__.'/../views/form_producto.php';} function guardar(){ $d=$_POST; $this->m->guardar($d);header('Location:index.php?controller=producto&action=listar');exit;} function editar(){$producto=$this->m->obtener((int)($_GET['id']??0));require __DIR__.'/../views/form_producto.php';} function actualizar(){ $d=$_POST;$this->m->actualizar($d);header('Location:index.php?controller=producto&action=listar');exit;} function publicar(){ $id=(int)($_GET['id']??0);$estado=(int)($_GET['estado']??0);$this->m->publicar($id,$estado);header('Location:index.php?controller=producto&action=listar');exit;} function eliminar(){$this->m->eliminar((int)($_GET['id']??0));header('Location:index.php?controller=producto&action=listar');exit;} }
?>
